const name = 'vis_layers';
// Setting default empty arrays for null & undefined edge cases
export const visLayers = {
  name,
  from: {
    null: () => {
      return {
        type: name,
        layers: []
      };
    },
    undefined: () => {
      return {
        type: name,
        layers: []
      };
    }
  }
};